  .ds-chat-prose code {
    font-family: var(--ui-font-mono);
    font-optical-sizing: auto;
    font-size: var(--ui-text-mono);
    font-style: normal;
    font-weight: var(--ui-weight-mono);
    font-variation-settings: var(--ui-font-var-mono);
    letter-spacing: var(--ui-tracking-mono);
    background-color: var(--ui-color-surface-secondary);
    border-radius: var(--ui-chat-prose-code-radius);
    padding: 1px var(--ui-spacing-xxs);
  }
  .ds-chat-prose pre {
    overflow-x: auto;
    border-radius: var(--ui-radius-tight);
    background-color: var(--ui-color-surface-secondary);
    padding: var(--ui-spacing-rg);
    box-shadow: var(--ui-shadow-button);
  }
  .ds-chat-prose pre code {
    background-color: transparent;
    padding: 0;
    border-radius: 0;
  }
  .ds-chat-prose table {
    border-collapse: collapse;
  }
  .ds-chat-prose :is(td, th) {
    border: 1px solid var(--ui-color-border-primary);
